// Worker environment. `Env` (bindings, vars, secrets) is generated by
// `npx wrangler types` into worker-configuration.d.ts.

export interface AppEnv extends Env {
  /**
   * Optional override for the Claude API base URL. Unset in production (the SDK
   * default, https://api.anthropic.com, is used); the tests point it at a mock.
   */
  ANTHROPIC_BASE_URL?: string;
}

export const DEFAULT_DAILY_LIMIT = 200;
export const DEFAULT_MODEL = "claude-opus-5-5";

/** The DAILY_LIMIT var as a number (falls back to 200 if unset or malformed). */
export function defaultDailyLimit(env: AppEnv): number {
  const n = Number.parseInt(env.DAILY_LIMIT ?? "", 10);
  return Number.isFinite(n) && n >= 0 ? n : DEFAULT_DAILY_LIMIT;
}

export function modelId(env: AppEnv): string {
  return env.MODEL?.trim() || DEFAULT_MODEL;
}
